import { l as menuCategories, t as db, u as menuItems } from "../../../../../chunks/db.js";
import { i as superValidate } from "../../../../../chunks/client2.js";
import "../../../../../chunks/dist3.js";
import { t as zod } from "../../../../../chunks/adapters.js";
import { n as sortOrderField, t as contentCrud } from "../../../../../chunks/crud.js";
import { asc, eq } from "drizzle-orm";
import { z } from "zod/v4";
//#region src/routes/dashboard/content/menu-items/schema.ts
var addSchema = z.object({
	categoryId: z.coerce.number("Required").int().positive(),
	name: z.string("Required").min(1, "Required").max(120),
	description: z.string().max(600).optional(),
	/** Entered in pounds, stored in pence. */
	price: z.coerce.number("Required").min(0).max(999).transform((v) => Math.round(v * 100)),
	image: z.file().max(1e7).optional(),
	isVegan: z.boolean().default(false),
	isVegetarian: z.boolean().default(false),
	isSpicy: z.boolean().default(false),
	/** One allergen per line; the UK's 14 declarable allergens. */
	allergens: z.string().optional(),
	isAvailable: z.boolean().default(true),
	isSignature: z.boolean().default(false),
	sortOrder: sortOrderField
});
var editSchema = addSchema.extend({
	id: z.coerce.number(),
	image: z.file().max(1e7).optional()
});
var toggleSchema = z.object({
	id: z.coerce.number(),
	isAvailable: z.coerce.boolean()
});
//#endregion
//#region src/routes/dashboard/content/menu-items/+page.server.ts
var crud = contentCrud({
	table: menuItems,
	label: "Dish",
	addSchema,
	editSchema,
	fileFields: ["image"],
	listFields: ["allergens"]
});
var load = async () => {
	const [base, categories, toggleForm] = await Promise.all([
		crud.load(),
		db.select().from(menuCategories).orderBy(asc(menuCategories.sortOrder)),
		superValidate(zod(toggleSchema))
	]);
	return {
		...base,
		categories,
		toggleForm
	};
};
var actions = {
	...crud.actions,
	toggleAvailability: async ({ request }) => {
		const form = await superValidate(request, zod(toggleSchema));
		if (!form.valid) return { form };
		await db.update(menuItems).set({ isAvailable: form.data.isAvailable }).where(eq(menuItems.id, form.data.id));
		return { form };
	}
};
//#endregion
export { actions, load };
